function _rng(seed){ var s=seed>>>0||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }
function ppPredict(w, x){ var s=w[w.length-1]; for(var i=0;i<x.length;i++) s+=w[i]*x[i]; return s>=0?1:-1; }
function ppTrain(w, x, y, lr){
  if(ppPredict(w,x)!==y){ for(var i=0;i<x.length;i++) w[i]+=lr*y*x[i]; w[w.length-1]+=lr*y; }
  return w;
}
function ppData(n, rnd, wtrue){
  var pts=[]; for(var i=0;i<n;i++){ var x=[rnd()*2-1, rnd()*2-1];
    var s=wtrue[0]*x[0]+wtrue[1]*x[1]+wtrue[2]; pts.push({x:x, y: s>=0?1:-1}); }
  return pts;
}
function ppAccuracy(w, data){ var c=0; for(var i=0;i<data.length;i++) if(ppPredict(w,data[i].x)===data[i].y) c++; return c/data.length; }
var EXPORTS={ppPredict:ppPredict, ppTrain:ppTrain, ppData:ppData, ppAccuracy:ppAccuracy, _rng:_rng};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PerceptronForgePure = EXPORTS; }
